def transform(grid):
    h, w = len(grid), len(grid[0])
    groups = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                groups.setdefault(color, []).append((r, c))
    if not groups:
        return [row[:] for row in grid]

    # The colored diagonal bands encode a periodic coloring. Their invariant
    # (r+c or r-c) determines the matching output stripe.
    invariants = (lambda r, c: r + c, lambda r, c: r - c)
    scores = []
    for inv in invariants:
        scores.append(sum(len(cells) for cells in groups.values()
                          if len({inv(r, c) for r, c in cells}) == 1))
    inv = invariants[scores.index(max(scores))]
    period = len(groups)
    residue_to_color = {}
    for color, cells in groups.items():
        values = {inv(r, c) for r, c in cells}
        if len(values) == 1:
            residue_to_color[next(iter(values)) % period] = color
    return [[residue_to_color[inv(r, c) % period] for c in range(w)]
            for r in range(h)]
